INSERT INTO "stock" VALUES(3,'EL34','1',4,'Svetlana',NULL,'2026-08-09','The EL34 is a much loved audio power Pentode valve with an anode dissipation of 25 Watts.',NULL,NULL,NULL,NULL,NULL,NULL);
