INSERT INTO "stock" VALUES(10,'12AX7','1',1,NULL,NULL,'2026-08-09','High Impedance Pre- Amplifier Triode',NULL,NULL,NULL,NULL,NULL,NULL);
INSERT INTO "stock" VALUES(11,'30C17','2',1,'Pinnacle',NULL,'2026-08-09','The 30C17 is a triode variable-mu pentode designed for television frequency changer use.',NULL,NULL,NULL,NULL,NULL,NULL);
INSERT INTO "stock" VALUES(12,'30FL1','2',1,'Mazda',NULL,'2026-08-09','Low Power, low annode voltage, General Purpose Tetrode',NULL,NULL,NULL,NULL,NULL,NULL);
INSERT INTO "stock" VALUES(13,'30FL2','2',1,'Pinnacle',NULL,'2026-08-09','The 30FL2 is a television valve in a miniature envelope, the 6FL2 is identical except for the heater, which is 6.3 V at 0.5 A.  The triode, low power beam tetrode was designed as line time base and sync separator.',NULL,NULL,NULL,NULL,NULL,NULL);
INSERT INTO "stock" VALUES(14,'30L1','2',1,'Pinnacle',NULL,'2026-08-09','The 30L1 is a double triode developed to meet the needs of VHF band III television transmission in the 1950s. designed for cascode operation. The normal configuration was for triode one to be operated as a grounded cathode stage directly coupled to triode two connected as a grounded grid stage',NULL,NULL,NULL,NULL,NULL,NULL);
INSERT INTO "stock" VALUES(15,'6F25','2',1,'Mazda',NULL,'2026-08-09','The EF183 is a high gain variable μ RF amplifier pentode. It',NULL,NULL,NULL,NULL,NULL,NULL);
INSERT INTO "stock" VALUES(16,'6F26','2',1,'Mazda',NULL,'2026-08-09','The 6F26 is a VHF varible-mu pentode where the stage gain is controlled by the negative bias applied to the control grid.',NULL,NULL,NULL,NULL,NULL,NULL);
INSERT INTO "stock" VALUES(17,'6F28','2',1,'Mazda',NULL,'2026-08-09','Beam Tetrode Wide Band Amplifier',NULL,NULL,NULL,NULL,NULL,NULL);
INSERT INTO "stock" VALUES(18,'6F29','2',1,'Mazda',NULL,'2026-08-09','The 6F29 is a high gain variable μ RF amplifier pentode. (40Mhz)',NULL,NULL,NULL,NULL,NULL,NULL);
INSERT INTO "stock" VALUES(19,'6F30','2',1,'Mazda',NULL,'2026-08-09','Screen-grid Tetrode   Power/Output',NULL,NULL,NULL,NULL,NULL,NULL);
INSERT INTO "stock" VALUES(20,'D77','2',1,'Osram',NULL,'2026-08-09','Dual Diode',NULL,NULL,NULL,NULL,NULL,NULL);
INSERT INTO "stock" VALUES(21,'DAF96','2',2,'Mullard',NULL,'2026-08-09','Detector, First Audio stage, Low Current consumption',NULL,NULL,NULL,NULL,NULL,NULL);
INSERT INTO "stock" VALUES(22,'DF96','2',2,'Mullard',NULL,'2026-08-09','Pentode, IF Amplifier, Low Current Consumption',NULL,NULL,NULL,NULL,NULL,NULL);
INSERT INTO "stock" VALUES(23,'DK96','2',4,'Mullard',NULL,'2026-08-09','Pentode/Triode Frequency Changed, Lower Current Consumption',NULL,NULL,NULL,NULL,NULL,NULL);
INSERT INTO "stock" VALUES(24,'DL96','2',1,'everready',NULL,'2026-08-09','Audio Output, 200mw, Tetrode',NULL,NULL,NULL,NULL,NULL,NULL);
INSERT INTO "stock" VALUES(25,'DY86','2',1,'Pinnacle',NULL,'2026-08-09','The DY86 is a television EHT rectifier. It was designed to have its heater supply produced by an overwind on the line output transformer. The 18,000 Volt rating places this as a rectifier for medium sized monochrome televisions.',NULL,NULL,NULL,NULL,NULL,NULL);
INSERT INTO "stock" VALUES(26,'EB91','2',1,'marconi',NULL,'2026-08-09','Dual Diode',NULL,NULL,NULL,NULL,NULL,NULL);
INSERT INTO "stock" VALUES(27,'EB91','2',1,'Pinnacle',NULL,'2026-08-09','Double Diode   Detector',NULL,NULL,NULL,NULL,NULL,NULL);
INSERT INTO "stock" VALUES(28,'EBF80','2',1,'Mullard',NULL,'2026-08-09','The EBF80 is a variable μ amplifier pentode and a pair of signal diodes in the one envelope. Final IF Amplifier',NULL,NULL,NULL,NULL,NULL,NULL);
INSERT INTO "stock" VALUES(29,'EBF89','2',1,'Mullard',NULL,'2026-08-09','he EBF89 features two signal diodes and a variable μ pentode in the one envelope and sharing a common cathode. The variable μ characteristic is indicative of a device designed to have its gain controlled by an AGC system.',NULL,NULL,NULL,NULL,NULL,NULL);
INSERT INTO "stock" VALUES(30,'EC86','2',1,NULL,NULL,'2026-08-09','Grounded Grid UHF Amplifier, 400-800Mhz',NULL,NULL,NULL,NULL,NULL,NULL);
INSERT INTO "stock" VALUES(31,'EF183','2',1,'Pinnacle',NULL,'2026-08-09','The EF183 is a high gain variable μ RF amplifier pentode. It is a late 1950s design and superseded the EF85. The EF184 was the straight version of the design and replaced the EF80. All four valves have the same pin connections.',NULL,NULL,NULL,NULL,NULL,NULL);
INSERT INTO "stock" VALUES(32,'EF80','2',1,'Mullard',NULL,'2026-08-09','internally screened pentode was a workhorse of the VHF TV receiver and was introduced in mid 1950 to replace the EF91. It was described by Mullard as: a high slope RF pentode and not a variable μ type',NULL,NULL,NULL,NULL,NULL,NULL);
INSERT INTO "stock" VALUES(33,'EF80','2',1,'Pinnacle',NULL,'2026-08-09','internally screened pentode was a workhorse of the VHF TV receiver and was introduced in mid 1950 to replace the EF91. It was described by Mullard as: a high slope RF pentode and not a variable μ type',NULL,NULL,NULL,NULL,NULL,NULL);
INSERT INTO "stock" VALUES(34,'EL41','2',1,'Pinnacle',NULL,'2026-08-09','The EL41 is an early all glass output pentode. Mullard describe the EL41 as an output pentode rated for 9 watts anode dissipation, and intended primarily for use in AC mains operated equipment. They state that the EL41 should only be used with self-bias or semi-automatic bias',NULL,NULL,NULL,NULL,NULL,NULL);
INSERT INTO "stock" VALUES(35,'EM84','2',4,'Mullard',NULL,'2026-08-09','Magic Eye Tuning',NULL,NULL,NULL,NULL,NULL,NULL);
INSERT INTO "stock" VALUES(36,'EY51','2',1,'Mullard',NULL,'2026-08-09','he EY51 is a wire-ended EHT rectifier with a 6.3 V 90 mA heater which is normally fed from a well-insulated winding on the line output transformer of a television',NULL,NULL,NULL,NULL,NULL,NULL);
INSERT INTO "stock" VALUES(37,'PC86','2',1,'Mullard',NULL,'2026-08-09','The PC86 is a purpose designed UHF oscillator triode for television reception',NULL,NULL,NULL,NULL,NULL,NULL);
INSERT INTO "stock" VALUES(38,'PC88','2',1,'Mullard',NULL,'2026-08-09','The PC88 is a UHF triode designed for grounded grid operation in the front end RF amplifier in Band IV and Band V television tuners',NULL,NULL,NULL,NULL,NULL,NULL);
INSERT INTO "stock" VALUES(39,'PCC189','2',1,'Mullard',NULL,'2026-08-09','The PCC189 is a low impedance high gain double triode for use as a cascode amplifier in television front-ends. It specifically states that it is built with frame grids. The valves are variable μ types for use at RF as AGC controlled devices.',NULL,NULL,NULL,NULL,NULL,NULL);
INSERT INTO "stock" VALUES(40,'PCC84','2',1,'Mullard',NULL,'2026-08-09','double triode shows how valves developed to meet the needs of VHF television transmission.',NULL,NULL,NULL,NULL,NULL,NULL);
INSERT INTO "stock" VALUES(41,'PCL800','2',1,'Mullard',NULL,'2026-08-09','Triode output pentode designed for field timebase or audio service. The PCL800 is a television receiver valve with a 300 mA heater for use with series heater chains. Domestic televisions worked at mains voltage and did not have a mains transformer.',NULL,NULL,NULL,NULL,NULL,NULL);
INSERT INTO "stock" VALUES(42,'PCL85','2',2,'Pinnacle',NULL,'2026-08-09','The PCL85 is a triode and output pentode combined. [was listed as PCL805/85]',NULL,NULL,NULL,NULL,NULL,NULL);
INSERT INTO "stock" VALUES(43,'PCL85','2',2,'Mazda',NULL,'2026-08-09','The PCL85 is a triode and output pentode combined.',NULL,NULL,NULL,NULL,NULL,NULL);
INSERT INTO "stock" VALUES(44,'PCL86','2',1,'Mullard',NULL,'2026-08-09','This PCL86 was made in the UK by Mullard and was designed for the audio stage of a television receiver and offered a quality output at about 4W. Pentode, Triode.',NULL,NULL,NULL,NULL,NULL,NULL);
INSERT INTO "stock" VALUES(45,'PF200','2',1,'Mullard',NULL,'2026-08-09','The PFL200 combines a screened amplifier pentode and an output pentode in the one envelope. It was designed for television use, but probably not for audio output as the operating conditions do not give an output power. The mutual conductance of the output pentode at 21 is very high, pointing to a very small space between cathode and control grid.',NULL,NULL,NULL,NULL,NULL,NULL);
INSERT INTO "stock" VALUES(46,'PL81','2',1,'Mullard',NULL,'2026-08-09','The PL81 Line Ouput, 6KV was designed for universal mains sets without a mains transformer and with the heaters on a series chain. The parameters given are for a pair in push pull audio service.',NULL,NULL,NULL,NULL,NULL,NULL);
INSERT INTO "stock" VALUES(47,'PL83','2',1,'Debanks',NULL,'2026-08-09','This is a true pentode with three wire grids. Used for video amplifier',NULL,NULL,NULL,NULL,NULL,NULL);
INSERT INTO "stock" VALUES(48,'PY80','2',1,'Mullard',NULL,'2026-08-09','The PY80 is an early efficiency diode for television line scan systems and was part of the world series valves introduced by Mullard in 1950. The maximum peak inverse voltage on the anode has to be under 4 kV. The peak heater to cathode voltage has to be under 650 Volts.',NULL,NULL,NULL,NULL,NULL,NULL);
INSERT INTO "stock" VALUES(49,'PY800','2',1,'Mullard',NULL,'2026-08-09','The PY800 was one of the last rectifiers of its type to be developed and is based on the PY81 from 1952. It was specifically built as an efficiency diode for television line scan in sets using 110° deflection angle tubes.',NULL,NULL,NULL,NULL,NULL,NULL);
INSERT INTO "stock" VALUES(50,'PY88','2',1,'Pinnacle',NULL,'2026-08-09','he PY88 is an efficiency diode for use in television line scan systems, where stored energy in the inductances is returned to the HT rail capacitors. The maximum peak inverse voltage (PIV) rating is 6,600 Volts. The peak anode current is 550 mA. These diodes require a very good heater cathode insulation and the PY88 is rated at 6,600 Volts.',NULL,NULL,NULL,NULL,NULL,NULL);
INSERT INTO "stock" VALUES(51,'U25','2',1,'Mazda',NULL,'2026-08-09','The U25 is a dedicated television EHT rectifier for picture tube supplies. The Mullard code for this valve would be KY50 but U25 was the standard name. The valve is rated at 19 kV peak inverse volts',NULL,NULL,NULL,NULL,NULL,NULL);
INSERT INTO "stock" VALUES(52,'U282','2',1,'Mazda',NULL,'2026-08-09','The U282 is a television efficiency diode, used to return energy from the collapsing field in the line coils to the HT rail. The peak current is given as 600 mA',NULL,NULL,NULL,NULL,NULL,NULL);
INSERT INTO "stock" VALUES(53,'UCC85','2',1,'Mullard',NULL,'2026-08-09','The UCC85 is the universal supply version of the ECC85 VHF double triode, designed for RF amplifier and local oscillator use in FM radio receivers.',NULL,NULL,NULL,NULL,NULL,NULL);
INSERT INTO "stock" VALUES(54,'UCC85','2',1,'Pinnacle',NULL,'2026-08-09','The UCC85 is the universal supply version of the ECC85 VHF double triode, designed for RF amplifier and local oscillator use',NULL,NULL,NULL,NULL,NULL,NULL);
INSERT INTO "stock" VALUES(55,'UL41','2',1,'Debanks',NULL,'2026-08-09','The UL41 is an audio output pentode from 1953. The U series were designed to operate with a heater chain across the mains in the days when AC mains had not reached all parts of the country. These universal sets contained no mains transformers and the valves were designed for low anode voltage and higher anode current to provide adequate output. The UL41 could produce 4.2 Watts at 10% distortion.',NULL,NULL,NULL,NULL,NULL,NULL);
INSERT INTO "stock" VALUES(56,'UL84','2',1,'Pinnacle',NULL,'2026-08-09','Beam Tetrode, The Mullard EL84 is a classic audio pentode valve, immortalised in the 1950s 5-10 design for an audio amplifier. The UL84 was designed with a 100 mA heater, for use in universal voltage environments and thus with limited HT available.',NULL,NULL,NULL,NULL,NULL,NULL);
INSERT INTO "stock" VALUES(57,'30C15','3',1,NULL,NULL,'2026-08-09','The 30C15 is a triode pentode designed for frequency changer use in VHF television receivers and is the high gain version of the 30C1.',NULL,NULL,NULL,NULL,NULL,NULL);
INSERT INTO "stock" VALUES(58,'30C17','3',1,NULL,NULL,'2026-08-09','The 30C17 is a triode variable-mu pentode designed for television frequency changer use. When introduced it was the first variable μ TV frequency changer to be available in the UK.',NULL,NULL,NULL,NULL,NULL,NULL);
INSERT INTO "stock" VALUES(59,'30FL2','3',6,NULL,NULL,'2026-08-09','The triode, low power beam tetrode was designed as line time base and sync separator.',NULL,NULL,NULL,NULL,NULL,NULL);
INSERT INTO "stock" VALUES(60,'30L1','3',1,NULL,NULL,'2026-08-09','The 30L1 is a double triode developed to meet the needs of VHF band III television transmission in the 1950s.',NULL,NULL,NULL,NULL,NULL,NULL);
INSERT INTO "stock" VALUES(61,'30P12','3',1,NULL,NULL,'2026-08-09','The 30P12 beam tetrode was designed as a single ended audio amplifier output valve for television receiver use or as a TV frame scan output valve.',NULL,NULL,NULL,NULL,NULL,NULL);
INSERT INTO "stock" VALUES(62,'30PL1','3',4,NULL,NULL,'2026-08-09','The 30PL1 is an output pentode. Designed for use on 300 mA heater chains, normally found in domestic televisions, it can be used for audio output, with an anode load of 6,000 Ohms, or as a frame timebase stage.',NULL,NULL,NULL,NULL,NULL,NULL);
INSERT INTO "stock" VALUES(63,'30PL14','3',3,NULL,NULL,'2026-08-09','Beam Tetrode for frame output',NULL,NULL,NULL,NULL,NULL,NULL);
INSERT INTO "stock" VALUES(64,'6F28','3',2,NULL,NULL,'2026-08-09','The 6F28 is an amplifier beam tetrode of high mutual conductance designed for television service and introduced by Thorn-AEI (Mazda) in 1961',NULL,NULL,NULL,NULL,NULL,NULL);
INSERT INTO "stock" VALUES(65,'DY802','3',2,NULL,NULL,'2026-08-09','Rectofier, The DY802 is designed for a maximum PIV of 30,000 Volts and will produce an output voltage of 20,000 Volts.',NULL,NULL,NULL,NULL,NULL,NULL);
INSERT INTO "stock" VALUES(66,'DY86','3',7,NULL,NULL,'2026-08-09','The DY86 is a television EHT rectifier. It was designed to have its heater supply produced by an overwind on the line output transformer. The 18,000 Volt rating',NULL,NULL,NULL,NULL,NULL,NULL);
INSERT INTO "stock" VALUES(67,'EB91','3',1,NULL,NULL,'2026-08-09','The EB91 is a double signal diode.',NULL,NULL,NULL,NULL,NULL,NULL);
INSERT INTO "stock" VALUES(68,'ECH84','3',1,NULL,NULL,'2026-08-09','The ECH84 is a low voltage triode heptode. The triode heptode was designed for noise immune TV sync separators.',NULL,NULL,NULL,NULL,NULL,NULL);
INSERT INTO "stock" VALUES(69,'EF183','3',1,NULL,NULL,'2026-08-09','The EF183 is a high gain variable μ RF amplifier pentode',NULL,NULL,NULL,NULL,NULL,NULL);
INSERT INTO "stock" VALUES(70,'EF91','3',1,NULL,NULL,'2026-08-09','The EF91 is a high gain, high impedance, high slope, screened pentode. Mullard describe the EF91 as primarily intended for use as RF amplifiers or mixer valves in television receivers.',NULL,NULL,NULL,NULL,NULL,NULL);
INSERT INTO "stock" VALUES(71,'PC88','3',3,NULL,NULL,'2026-08-09','The PC88 is a UHF triode designed for grounded grid operation in the front end RF amplifier',NULL,NULL,NULL,NULL,NULL,NULL);
INSERT INTO "stock" VALUES(72,'PC900','3',6,NULL,NULL,'2026-08-09','The PC900 is a miniature VHF amplifier triode for use as an RF amplifier in television receivers',NULL,NULL,NULL,NULL,NULL,NULL);
INSERT INTO "stock" VALUES(73,'PC97','3',1,NULL,NULL,'2026-08-09','The PC97 is a VHF triode. It has a high mutual conductance and could be used as a signal pre-amplifier',NULL,NULL,NULL,NULL,NULL,NULL);
INSERT INTO "stock" VALUES(74,'PCF80','3',1,NULL,NULL,'2026-08-09','The valve is a triode pentode, with separate cathodes, designed to function as a mixer and oscillator in the tuner.',NULL,NULL,NULL,NULL,NULL,NULL);
INSERT INTO "stock" VALUES(75,'PCF801','3',2,NULL,NULL,'2026-08-09','The PCF801 is a television mixer oscillator. Triode pentode combinations worked better at high frequencies than hexode mixers.',NULL,NULL,NULL,NULL,NULL,NULL);
INSERT INTO "stock" VALUES(76,'PCF805','3',3,NULL,NULL,'2026-08-09','purpose designed oscillator and mixer for frequency changer use in VHF television receivers.',NULL,NULL,NULL,NULL,NULL,NULL);
INSERT INTO "stock" VALUES(77,'PCF806','3',1,NULL,NULL,'2026-08-09','triode and frame-grid pentode frequency changer for VHF television receivers up to 220 MHz.',NULL,NULL,NULL,NULL,NULL,NULL);
INSERT INTO "stock" VALUES(78,'PCH200','3',2,NULL,NULL,'2026-08-09','triode heptode. The triode was designed as a pulse amplifier and the heptode section was designed for service as a noise gated sync. separator in colour television receivers.',NULL,NULL,NULL,NULL,NULL,NULL);
INSERT INTO "stock" VALUES(79,'PCL805','3',1,NULL,NULL,'2026-08-09','triode pentode was purpose designed as a domestic television receiver frame output stage.',NULL,NULL,NULL,NULL,NULL,NULL);
INSERT INTO "stock" VALUES(80,'PCL84','3',2,NULL,NULL,'2026-08-09','general purpose triode and a video output pentode in the one envelop',NULL,NULL,NULL,NULL,NULL,NULL);
INSERT INTO "stock" VALUES(81,'PFL200','3',2,NULL,NULL,'2026-08-09','two separate pentode valves in one package. For consumer electronics products cost reduction was vital, and the more functionality within each envelope the bette',NULL,NULL,NULL,NULL,NULL,NULL);
INSERT INTO "stock" VALUES(82,'PL802','3',3,NULL,NULL,'2026-08-09','purpose designed video output pentode for driving a cathode ray tube with the wide bandwidth signal needed for colour TV picture information. 300V at 6 watts',NULL,NULL,NULL,NULL,NULL,NULL);
INSERT INTO "stock" VALUES(83,'PL84','3',1,NULL,NULL,'2026-08-09','audio output pentode was designed for use in television receivers. Like the UL84 with a 100mA heater it is a low voltage high current version of the EL84, itself a standard in design.',NULL,NULL,NULL,NULL,NULL,NULL);
INSERT INTO "stock" VALUES(84,'PCL83','3',1,NULL,NULL,'2026-08-09','television triode output pentode. It is used as a frame timebase and frame output stage or audio output stage if required.',NULL,NULL,NULL,NULL,NULL,NULL);
INSERT INTO "stock" VALUES(85,'PY800','3',2,NULL,NULL,'2026-08-09','The PY800 was one of the last rectifiers of its type to be developed and is based on the PY81 from 1952. It was specifically built as an efficiency diode for television line scan in sets using 110° deflection angle tubes.',NULL,NULL,NULL,NULL,NULL,NULL);
INSERT INTO "stock" VALUES(86,'PY801','3',1,NULL,NULL,'2026-08-09','The PY801 is a television efficiency diode for use in line timebase output circuits.',NULL,NULL,NULL,NULL,NULL,NULL);
INSERT INTO "stock" VALUES(87,'PY81','3',1,NULL,NULL,'2026-08-09','The PY81 was specifically built as an efficiency diode for television line scan',NULL,NULL,NULL,NULL,NULL,NULL);
INSERT INTO "stock" VALUES(88,'PY82','3',1,NULL,NULL,'2026-08-09','The PY82 is an efficiency diode for use in domestic television receivers.',NULL,NULL,NULL,NULL,NULL,NULL);
INSERT INTO "stock" VALUES(89,'PY83','3',1,NULL,NULL,'2026-08-09','The PY83 is an efficiency diode for use in television line scan circuits. The peak inverse anode voltage is 5,600 Volts and peak current is 500 mA.',NULL,NULL,NULL,NULL,NULL,NULL);
INSERT INTO "stock" VALUES(90,'PY86','3',1,NULL,NULL,'2026-08-09',NULL,NULL,NULL,NULL,NULL,NULL,NULL);
INSERT INTO "stock" VALUES(91,'PY88','3',2,NULL,NULL,'2026-08-09','The PY88 is an efficiency diode for use in television line scan systems',NULL,NULL,NULL,NULL,NULL,NULL);
INSERT INTO "stock" VALUES(92,'U26','3',1,NULL,NULL,'2026-08-09','The U26 is a purpose designed EHT rectifier for monochrome television',NULL,NULL,NULL,NULL,NULL,NULL);
INSERT INTO "stock" VALUES(93,'UABC80','3',1,NULL,NULL,'2026-08-09','The UABC80 is a triple diode triode',NULL,NULL,NULL,NULL,NULL,NULL);
INSERT INTO "stock" VALUES(94,'UAF42','3',1,NULL,NULL,'2026-08-09','The UAF42 is an early all glass valve introduced in 1948 together with the EAF42 and consists of a single diode and a variable μ RF amplifier pentode in a single envelope.',NULL,NULL,NULL,NULL,NULL,NULL);
INSERT INTO "stock" VALUES(95,'UY41','3',1,NULL,NULL,'2026-08-09','The UY41 is a half wave rectifier designed for universal domestic equipment and replaced the UY21. By universal we mean AC or DC mains input and therefore no mains transformer.',NULL,NULL,NULL,NULL,NULL,NULL);
INSERT INTO "stock" VALUES(96,'UY85','3',2,NULL,NULL,'2026-08-09','The UY85 is a half wave rectifier and would be used on small universal (AC/DC) mains appliances. The heater chain would draw 100 mA and this was to enable the small number of valves used in a broadcast radio receiver to be run without a large dropper (ballast) resister.',NULL,NULL,NULL,NULL,NULL,NULL);
INSERT INTO "stock" VALUES(97,'ECH42','4',1,NULL,NULL,'2026-08-09',NULL,NULL,NULL,NULL,NULL,NULL,NULL);
INSERT INTO "stock" VALUES(98,'ECC85','4',3,NULL,NULL,'2026-08-09',NULL,NULL,NULL,NULL,NULL,NULL,NULL);
INSERT INTO "stock" VALUES(99,'EBF89','4',1,NULL,NULL,'2026-08-09',NULL,NULL,NULL,NULL,NULL,NULL,NULL);
INSERT INTO "stock" VALUES(100,'UABC80','4',2,NULL,NULL,'2026-08-09',NULL,NULL,NULL,NULL,NULL,NULL,NULL);
