INSERT INTO "stock" VALUES(161,'PY800','5',3,NULL,NULL,'2026-08-09','The PY800 was one of the last rectifiers of its type to be developed and is based on the PY81 from 1952. It was specifically built as an efficiency diode for television line scan in sets using 110° deflection angle tubes.',NULL,NULL,NULL,NULL,NULL,NULL);
