INSERT INTO "stock" VALUES(214,'DH77','12',8,NULL,NULL,'2026-08-09','The DH77 amplifier triode with twin signal diodes on a common cathode. It was designed for use in superhet receivers at the end of the IF chain and as the first audio amplifier feeding the output stage.',NULL,NULL,NULL,NULL,NULL,NULL);
INSERT INTO "stock" VALUES(215,'EF91','12',9,NULL,NULL,'2026-08-09','a high gain, high impedance, high slope, screened pentode.',NULL,NULL,NULL,NULL,NULL,NULL);
