INSERT INTO "stock" VALUES(217,'6AU6','12',8,NULL,NULL,'2026-08-09','RF pentode for use up to 50 MHz.',NULL,NULL,NULL,NULL,NULL,NULL);
INSERT INTO "stock" VALUES(218,'6F23','12',4,NULL,NULL,'2026-08-09','screened amplifier pentode. The presence of two cathode connections suggests an RF role where lead inductance needs to kept to a minimum.',NULL,NULL,NULL,NULL,NULL,NULL);
INSERT INTO "stock" VALUES(219,'8D3','12',8,NULL,NULL,'2026-08-09','(EF91) universal amplifier pentode of the post war era, many manufacturers made versions of this standard valve. The version shown here was made by Brimar and is labelled for commercial use. The EF91 is a high gain, high impedance, sharp cut-off, screened pentode. It could be used from AF to VHF up to about 200 MHz and was found in large numbers in most types of electronic equipment.',NULL,NULL,NULL,NULL,NULL,NULL);
INSERT INTO "stock" VALUES(220,'U319','12',5,NULL,NULL,'2026-08-09','U319 is a half wave rectifier designed for 300 mA heater chain equipment.',NULL,NULL,NULL,NULL,NULL,NULL);
INSERT INTO "stock" VALUES(221,'EL95','12',6,NULL,NULL,'2026-08-09','EL95 is an output pentode with low heater consumption designed initially for car radios. It would also provide adequate audio power for a domestic receiver or smaller stereo system.',NULL,NULL,NULL,NULL,NULL,NULL);
INSERT INTO "stock" VALUES(222,'EC92','12',6,NULL,NULL,'2026-08-09','Single triode designed for use as a mixer, amplifier or oscillator in VHF television receivers.',NULL,NULL,NULL,NULL,NULL,NULL);
INSERT INTO "stock" VALUES(223,'EC91','12',8,NULL,NULL,'2026-08-09','miniature single triode. The Mullard manual describes the EC91 as a miniature screened triode for use as a grounded grid amplifier.',NULL,NULL,NULL,NULL,NULL,NULL);
INSERT INTO "stock" VALUES(224,'6F12','12',9,NULL,NULL,'2026-08-09','high gain, high impedance, high slope, screened pentode. The 6F12 was used in the 1948 Murphy V114 television receiver for RF and IF amplification.',NULL,NULL,NULL,NULL,NULL,NULL);
INSERT INTO "stock" VALUES(225,'DL96','12',6,NULL,NULL,'2026-08-09','audio output valve from Mullard''s low consumption dry battery valves from 1954. The audio output is low at 0.2 Watts but considering the low filament power it is quite remarkable.',NULL,NULL,NULL,NULL,NULL,NULL);
