INSERT INTO "valve_type" VALUES('10F1','10F1','RF pentode','british (Mazda/Brimar code)',NULL,NULL,10.0,NULL,NULL,NULL,NULL,NULL,NULL,NULL,'early all glass screened amplifier pentode. The high impedance suggests applications with tuned circuits as anode loads, such as RF, or more likely due to the high gain, IF amplification in superhet radio, television or radar receivers.',NULL,NULL,NULL,'inferred',NULL);
