INSERT INTO "valve_type" VALUES('150C4','150C4','voltage stabiliser (cold cathode)',NULL,'B7G',7,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,'Gas-filled reference tube that regulates a supply rail around 150V.',NULL,'1\150C4.pdf',NULL,'confirmed',NULL);
INSERT INTO "valve_type" VALUES('207','207','power triode (water-cooled)',NULL,NULL,2,22.0,52.0,15000.0,10000.0,NULL,20.0,NULL,NULL,'large water-cooled transmitting triode for high-power radio broadcast transmitters',NULL,'2\207.pdf',NULL,'confirmed',NULL);
INSERT INTO "valve_type" VALUES('210','210',NULL,NULL,'UX 4-pin',NULL,7.5,1.25,NULL,10.0,NULL,NULL,1.5,NULL,'Candidate ID: 1920s-30s American directly-heated power triode (RCA type ''10'' / UX-210), used as a small audio output valve and later as a low-power transmitting/oscillator triode.','UX-210 10 10Y 801A VT-25 VT-62',NULL,'https://www.radiomuseum.org/tubes/tube_ux210.html','inferred','Web research: LOW CONFIDENCE - ''210'' is a generic bare number that collides with unrelated products, and within valve nomenclature could equally mean the unrelated British Cossor 210HL (already a separate confirmed type in this inventory, 2V filament) rather than the American UX-210 (7.5V filament) described here. This project''s own stock note already flags this specific item as ''Unmarked, Suspected to be 210'' with no physical confirmation - treat all figures as a candidate lead only, not a confirmed identification.
INSERT INTO "valve_type" VALUES('210HL','210HL','triode',NULL,NULL,NULL,2.0,0.1,150.0,NULL,1.1,24.0,NULL,NULL,'leaky-grid detector stage in battery-powered valve radio receivers','CV1050 CV2571 HL2K K30C K30D K30K PM2HL VT50','2\210HL.pdf',NULL,'confirmed',NULL);
INSERT INTO "valve_type" VALUES('210SS','210 SS',NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,'As Above, by Manufacturere Six Sixty. Second Quality outlet for Mullart',NULL,NULL,NULL,'inferred','Web research: no independently verifiable technical data found for a valve marked ''210 SS'' - not documented as a distinct commercial type anywhere searched. This project''s own stock note already identifies it as ''by Manufacturer Six Sixty, Second Quality outlet for Mullard'' - external research confirms Six-Sixty (later bought by Mullard, sold on to Ever Ready in 1935) really did rebadge/sell second-quality Mullard valves, which is consistent with ''SS'' as a house/quality-grade marking rather than a real type suffix. But no source documents ''210 SS'' as an actual Six-Sixty catalogue number - remains unidentified.
INSERT INTO "valve_type" VALUES('220HPT','220HPT','output pentode',NULL,NULL,NULL,2.0,0.2,150.0,NULL,2.5,NULL,NULL,NULL,'economy output pentode for low-current battery-powered portable radios','KT2','2\220HPT.pdf',NULL,'confirmed',NULL);
INSERT INTO "valve_type" VALUES('2C34','2C34','double triode power amplifier/oscillator',NULL,'Medium Shell 7-Pin',7,6.3,0.8,300.0,5.0,4.2,13.0,16.0,80.0,'RF power amplifier or oscillator triode pair for transmitting equipment.','RK34','2\2C34.pdf',NULL,'confirmed',NULL);
INSERT INTO "valve_type" VALUES('2P29','2P29','RF/audio pentode',NULL,'8 pin',NULL,2.2,NULL,NULL,NULL,NULL,NULL,NULL,120.0,'Miniature, low-filament-current RF pentode for oscillator/small RF amplifier duty, likely portable/battery equipment.',NULL,'2\2P29.pdf','https://www.radiomuseum.org/tubes/tube_2p29l.html','confirmed','Web research: two distinct base/lead variants exist (2P29L = Loctal-8, 2P29P = flying leads) with slightly different heater current; could not determine which this inventory item is, so base/pins left blank and only the parameters common to both (heater voltage, frequency) applied.
INSERT INTO "valve_type" VALUES('2XX27N','2XX27N','RF pentode',NULL,NULL,NULL,2.2,NULL,NULL,NULL,NULL,NULL,NULL,NULL,'If you remove the aluminium screening case, you can discover a lovely valve inside.','2J27P, 2Z27,2SH7',NULL,NULL,'inferred','Web research: could NOT confirm a tube with this exact designation. Closest plausible match is Soviet 2Zh27L (2Ж27Л, subminiature HF pentode, heater 2.2V/57mA, Va 120V, Ia 1.9mA, gm 1.25mA/V, ~120MHz, equiv RV2/4P700 - https://www.radiomuseum.org/tubes/tube_2j27l.html), but the designation mismatch (XX vs Zh, N vs L) means this is NOT confirmed - not applied. Please verify the physical marking.
