INSERT INTO "valve_type" VALUES('41000A','4-1000A','power tetrode (radial-beam, transmitting)',NULL,'5-pin metal shell',5,7.5,21.4,6000.0,1000.0,10.0,6.9,4200.0,110.0,'RF power amplifier, oscillator or modulator, efficient well into VHF - two tubes deliver over 5000W in FM broadcast service at 110MHz.','8166',NULL,'https://frank.pocnet.net/sheets/140/8/8166.pdf','confirmed','User identified the physical valve as a 4-1000A, not the 3-1000Z this was previously recorded/researched as (both are real Eimac designations, but different tubes - 3-1000Z/8164 is a triode, 4-1000A/8166 is a tetrode). Data below is for the 4-1000A/8166 read from the original Eimac datasheet.
