INSERT INTO "valve_type" VALUES('3CX1200A7','3CX1200A7','power triode (transmitting)',NULL,NULL,NULL,7.5,21.0,5000.0,1200.0,NULL,NULL,NULL,NULL,'with socket and chimney Possibly not quite right',NULL,NULL,'https://tdsl.duncanamps.com/show.php?des=3CX1200A7','confirmed','Web research: heater/Va/Pa confirmed via Duncan TDSL. Base/pins not stated there; type code follows standard Eimac naming (3C=ceramic/metal, X=external/forced-air-cooled anode, 1200=Pa in W, A7=base revision) consistent with the socket-and-chimney note already on this box 8 stock entry. Function/heater/dissipation figures treated as confirmed; base/pins remain unconfirmed.');
