INSERT INTO "valve_type" VALUES('5U4C','5U4C',NULL,'american (RETMA code)',NULL,NULL,5.0,NULL,NULL,NULL,NULL,NULL,NULL,NULL,'Russian 5C4S rectifier tube is equivalent to the 5Z4 / CV1863 / 5Z4GT / 5U4C.','5C4S',NULL,NULL,'inferred','Web research: LOW CONFIDENCE - could not find a manufacturer datasheet or reputable reference documenting ''5U4C'' as a distinct, standardised type. Radiomuseum''s thorough 5U4-family index (5U4/5U4G/5U4GB/5R4/5Z4) has no 5U4C entry; only an unreliable auto-generated-looking source claimed it exists. Likely close to 5U4G (5V/3A heater, ~1550V PIV) but NOT applied to the record - verify the actual tube marking before trusting any 5U4G-derived figures for this item.
