INSERT INTO "valve_type" VALUES('6C51HB','6C51H-B','nuvistor triode',NULL,NULL,NULL,6.3,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,'6S51N-V',NULL,NULL,'inferred','Triode for amplifying and generation. | Envelope: sub-miniature, metal-ceramic. | Mass 3 g. | General characteristics: | Type 6S51N 6S51N-V | Filament voltage, Volt 6.3 6.3 | Anode voltage, Volt 80 80 | Resistance in cathode circuit, Ohm 130 130 | Type 6S51N 6S51N-V | Filament (heater) current, mA 130±20 130±20 | Anode current, mA 9,5±2,8 10±2,5 | Reverse grid current, mkA -- £0,1 | Dissipate cathode-heater current, mkA £20 £20 | Mutual conductance, mA/V 7,5 to 12 11±2,5 | Gain coefficient 32±12 30±12 | Input resistance, Kohm 7 7 | Equivalent noise resistance, Ohm -- £0,4 | Vibration noise (by R | A =2 KOhm), mV £40 £40 | Inter electrode capacitance, pF: | input 4,2±1,3 4,2±0,8 | output 1,8±0,6 2,2±0,6 | transfer £2,5 1,8±0,6 | cathode-heater 1,4±0,4 1,4±0,4 | Operation time, h 5000 2000 | Limited operating values: | Type 6S51N, 6S51N-V | Filament voltage, V 5,7-7 | Anode voltage, V 120 | Grid voltage, V -55 | Cathode - heater voltage, V 100 | Cathode current, mA 15 | Anode dissipation, W 1,2 | Grid dissipation, W 0,2 | Resistance in grid circuit, MOhm 1 | Tubes temperature, ° 250 | Operating environmental conditions : | Type 6S51N 6S51N-V | Acceleration of vibration loads, g 2.5 15 | by frequencies, Hz 10-150 5-5000 | Acceleration of multiple impacts, g 35 150 | Acceleration of single impact, g -- 1000 | Continuos acceleration, g -- 150 | Ambient temperature, ° -60 to +125 -60 to +200 | Relative humidity at up to 40 °C, % 98 98');
