INSERT INTO "valve_type" VALUES('6H1NE8','6H1N-E8','double triode',NULL,NULL,NULL,6.3,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,'6n1p',NULL,NULL,'inferred','μ = 35 | Ia = 7.5 mA | S = 4.35 mA/V | Pa = 2.2 W | The 6N1P has similar ratings to the 6DJ8 and in the past was sometimes rebranded as such, however differences between the two types (the 6N1P requires almost twice the filament current and has only one third the S value) mean they are not directly interchangeable. The S is about 4.35 ma/V, the 6DJ8/ECC88 has a S of 12.5 ma/V and a gain of 33 and a lower internal resistance. However, the 6N1P is typically more linear for a given load. It is therefore inaccurate to say that these two tubes are identical. The correct Russian equivalent to the 6DJ8/ECC88 is the 6N23P, the latter has a S of 12.5 mA/V and a gain of 33.');
INSERT INTO "valve_type" VALUES('6H2N','6H2N','double triode',NULL,'9-pin (miniature glass envelope)',9,6.3,NULL,300.0,1.0,2.25,100.0,NULL,NULL,'The 6N2P, (Russian: 6Н2П), also sometimes spelled in English "6H2Pi", is a miniature 9-pin dual triode vacuum tube manufactured in USSR, Russia and China with characteristics similar to the 12AX7. The most significant difference between the two is that 6N2P has its two filament elements connected in parallel, unlike the series filament connection of the 12AX7, and it is thus only possible to operate it from a 6.3 volt, 340 mA filament supply (whereas a 12AX7 may be operated from either 6.3 or 12.6 volts, at 300 mA or 150 mA, respectively.)','6N2P','6\6N2P.pdf',NULL,'confirmed','Va/Pa/gm/mu ratings inherited from 6N2P''s datasheet - 6H2N''s own sheet is a heater-variant stub with identical electrode structure, differing only in heater rating (its own sheet''s heater figures are kept).
INSERT INTO "valve_type" VALUES('6J1P','6J1P','RF pentode',NULL,NULL,NULL,6.3,NULL,NULL,NULL,NULL,NULL,NULL,NULL,'The 6j1p is a high frequency pentode valve manufactured by the Voskhod factory in Russia. It is a seven-pin electronic component requiring a B7G base socket for connection, and 6.3 V for the heater filament. Using a 6j1p pentode as a triode is a very simple task, but unfortunately very few people understand how a pentode operates, however you might be wondering why use pentodes at all in the first place. Triodes are getting expensive due to their ever-dwindling stocks, and looking on eBay, the cost of a ECC81, ECC82, ECC83, and ECC85 has sky rocketed. However just recently I came across a cheap valve 6j1p selling for just one pound. It is very similar to the Russian 6z1p pentode and I was intrigued because there must be a factory out there making them!',NULL,NULL,NULL,'inferred',NULL);
INSERT INTO "valve_type" VALUES('6J5','6J5','detector amplifier triode',NULL,'Octal (6-pin)',6,6.3,0.3,300.0,2.5,2.6,20.0,NULL,NULL,'general-purpose small-signal triode amplifier or detector','6C5 CV1933 VT-94','6\6J5.pdf',NULL,'confirmed',NULL);
