INSERT INTO "valve_type" VALUES('6K7','6K7','variable-mu RF pentode',NULL,'Small Wafer Octal 7-Pin (Octal)',7,6.3,0.3,250.0,NULL,1.65,990.0,NULL,NULL,'RF/IF amplifier stage in AVC-equipped radio receivers',NULL,'6\6K7.pdf',NULL,'confirmed',NULL);
INSERT INTO "valve_type" VALUES('6N1N','6N1N','beam tetrode (output)',NULL,NULL,NULL,6.3,NULL,NULL,NULL,NULL,NULL,NULL,NULL,'The 6P1P (Russian: 6П1П) is a Soviet-made miniature 9-pin beam tetrode vacuum tube with ratings similar to the 6AQ5, EL90 and the 6V6. Because of a different pinout (a 9-pin base versus 7-pin base) than an 6AQ5/EL90, it cannot be used as a plug-in replacement for these types; however, it will work in the same circuit with component values unchanged. Its maximum plate/screen voltage and dissipation ratings are actually slightly higher than a 6AQ5. A ruggedized/extended ratings version of the tube is designated 6P1P-EV (Russian: 6П1П-ЕВ), roughly equivalent to the 6AQ5W. A Chinese-manufactured version of the tube also exists, labeled 6P1.','6p1p',NULL,NULL,'inferred',NULL);
