INSERT INTO "valve_type" VALUES('726A','726A','reflex klystron',NULL,NULL,NULL,6.3,NULL,NULL,NULL,NULL,NULL,NULL,NULL,'Klystron This reflex klystron was designed for microwave RF generation of about 20 mW about 9.7 GHz. It produces a continuous output and can be modulated for communications use. The output power is taken from the probe by passing the tip into waveguide. The base for this valve is special but an International Octal holder with pin four drilled out is equivalent.',NULL,NULL,NULL,'inferred',NULL);
