INSERT INTO "valve_type" VALUES('7609','JAN 7609','transmitting tetrode (ruggedised for mobile/vibration service)',NULL,'8-pin loctal',8,26.5,0.57,2000.0,150.0,NULL,NULL,NULL,500.0,'JAN military-spec ruggedised version of the Eimac 4X150D beam power tetrode, for RF amplifier/oscillator/multiplier duty up to UHF.','4X150D 7035 QEL1/150H CV9785',NULL,'https://www.radiomuseum.org/tubes/tube_7609.html','confirmed','Web research: function/base/heater/4X150D-equivalence confirmed specifically for 7609 via Radiomuseum. Numeric anode voltage/dissipation/frequency figures are from general 4X150-family data (several rated classes exist: CCS/ICAS, telephony/telegraphy) rather than a 7609-specific sheet, so treat as representative rather than precise.
