INSERT INTO "valve_type" VALUES('8D3','8D3','RF pentode',NULL,'Miniature (7-pin)',7,6.3,0.3,300.0,2.5,7.65,70.0,NULL,NULL,'British service-code equivalent of the EF91 (confirmed via multiple sources) - ratings inherited from EF91''s own datasheet.','EF91 Z77 6AM6 6F12 CV138 M8083',NULL,'https://www.radiomuseum.org/tubes/tube_ef91.html','confirmed','Web research: confirmed equivalent to EF91 via Radiomuseum and an independent retailer listing (mullard.org). Electrical ratings inherited from this project''s own EF91 record.
