INSERT INTO "valve_type" VALUES('BVA267','BVA 267','output pentode','european (Mullard/Philips code)','Octal (International Octal, K8A)',8,6.3,0.9,NULL,9.0,9.5,NULL,4.0,NULL,'BVA store-code equivalent of the Mullard EL33, a 1938-era AC-mains audio output pentode used as the output stage in domestic radio receivers.','EL33 6M6G N147 EL3NG CV1853 BVA264 BVA265',NULL,'https://www.radiomuseum.org/tubes/tube_el33.html','confirmed','Web research: two independent sources (Radiomuseum, a French vintage-tube retailer) both explicitly list BVA267=EL33, matching this project''s own prior note.
INSERT INTO "valve_type" VALUES('CF15N2','CF15N-2','voltage stabiliser (cold cathode)',NULL,'B7G (miniature 7-pin)',7,NULL,NULL,160.0,NULL,NULL,NULL,NULL,NULL,'Glow-discharge voltage reference tube, regulates at approx. 102-110V over 5-30mA.','SG15P-2',NULL,'https://rudatasheet.ru/tubes/sg15p-2/','inferred','Web research: identified as a likely transliteration/OCR variant of Soviet SG15P-2 (Cyrillic C/G/P visually resemble Latin C/F/N) - sources agree on the SG15P-2 data, but the CF15N-2 to SG15P-2 mapping is inferred, not directly confirmed.
INSERT INTO "valve_type" VALUES('CV124','CV124','beam tetrode (transmitting)',NULL,NULL,NULL,6.3,NULL,NULL,NULL,NULL,NULL,NULL,NULL,'he CV124 beam tetrode valve is unusual in being designated as current production in the 1960s and having a five pin base. The commercial equivalent was the classic 807.','807',NULL,NULL,'inferred',NULL);
INSERT INTO "valve_type" VALUES('CV1375','CV1375','variable-mu RF pentode',NULL,'B9A (Noval)',9,6.3,0.3,250.0,NULL,6.0,NULL,NULL,NULL,'Variable-mu RF/IF amplifier pentode for gain-controlled (AGC) stages in radio/TV receivers - same family as EF89.','EF85 6BY7 6F19 6F26 W719',NULL,'https://tdsl.duncanamps.com/show.php?des=CV1375','confirmed','Web research: confirmed via Duncan''s TDSL cross-reference to EF85, and a period Brimar/Thorn-AEI EF85 datasheet independently confirms ''variable-mu RF pentode'', matching this project''s existing guess.
INSERT INTO "valve_type" VALUES('CV1833','CV1833','voltage stabiliser (cold cathode)',NULL,'B7G (miniature 7-pin)',7,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,'Cold-cathode voltage-stabiliser tube, strikes at approx. 133V and regulates at approx. 108V over 5-30mA.','0B2 QS1208 CV4028 M8224 QS1211',NULL,'https://www.radiomuseum.org/tubes/tube_cv1833.html','confirmed','Web research: Radiomuseum explicitly states CV1833 is identical to QS1208=0B2, matching this project''s own prior note that 0B2 was the prototype for this CV spec.
INSERT INTO "valve_type" VALUES('CV2466','CV2466','double beam tetrode',NULL,'B9A (Noval)',9,6.3,0.8,180.0,6.0,NULL,NULL,6.0,490.0,'UK government designation for the Mullard QQV02-6, a twin beam-tetrode for push-pull/parallel VHF driver, multiplier, or low-power final-amplifier duty.','QQV02-6 6939',NULL,'https://www.r-type.org/exhib/aai0225.htm','confirmed','Web research: confirmed via The Valve Museum and valvecollector.uk, both explicitly equate CV2466 with QQV02-6, matching this project''s own prior note. Two sources gave slightly different max ratings (likely different heater-wiring modes) - both noted, this one used for the DB fields.
INSERT INTO "valve_type" VALUES('CV2799','CV2799','double beam tetrode',NULL,'Septar/B7A + 2 top caps',7,6.3,1.3,600.0,20.0,NULL,NULL,NULL,NULL,'Double beam tetrode for VHF/UHF transmitting duty up to 600MHz - RF amplifier, oscillator, modulator or frequency multiplier.','QQV03-20A 6252 C1134 RS1019',NULL,'https://www.radiomuseum.org/tubes/tube_cv2799.html','confirmed','Web research: two independent valve-specialist sites (valvecollector.uk, radiomuseum.org) agree closely; confirms existing ''double beam tetrode, 6.3V'' guess.
INSERT INTO "valve_type" VALUES('CV287','CV287','voltage stabiliser (cold cathode)',NULL,'B7G (miniature 7-pin)',7,NULL,NULL,177.0,NULL,NULL,NULL,NULL,NULL,'Gas-discharge voltage-reference tube, regulates at approx. 150V over approx. 2-15mA burning current.','150B3 QS150/15 150A2 ACT23 CV288',NULL,'https://www.radiomuseum.org/tubes/tube_cv287.html','confirmed','Web research: confirmed via Radiomuseum (manufacturer English Electric Valve Co); confirms existing ''voltage stabiliser, cold cathode'' guess.
INSERT INTO "valve_type" VALUES('CV320','CV320','cathode ray tube (CRT)',NULL,'B9 (9-pin)',9,4.0,1.1,800.0,NULL,NULL,NULL,NULL,NULL,'Small (~40mm) electrostatic-deflection CRT (Osram/GEC, YY2 ultra-short-persistence screen) for compact monitoring/oscilloscope-style display - not an amplifying valve.','CV1597 CV950 CV967',NULL,'https://www.valvecollector.uk/cv320.htm','confirmed','Web research: CONFIRMED as a genuine CRT via valvecollector.uk''s Virtual Valve Museum, which validates this project''s own prior note flagging it as possibly a CRT.
INSERT INTO "valve_type" VALUES('CV4014','CV4014','RF pentode',NULL,'Miniature (7-pin)',7,6.3,0.3,300.0,2.5,7.65,70.0,NULL,NULL,'British service-code equivalent of the EF91 (confirmed via multiple sources) - ratings inherited from EF91''s own datasheet.','EF91 Z77 6AM6 6F12 CV138 M8083',NULL,'https://www.radiomuseum.org/tubes/tube_ef91.html','confirmed','Web research: confirmed equivalent to EF91 via Radiomuseum and an independent retailer listing (mullard.org). Electrical ratings inherited from this project''s own EF91 record.
INSERT INTO "valve_type" VALUES('CV4060','CV4060','RF pentode (special quality)',NULL,NULL,NULL,6.3,NULL,NULL,NULL,NULL,NULL,NULL,NULL,'The CV4060 from AEI features a propane carbonised anode and dates from 1961. The commercial version is the S11E12. The screen grid is visible and is seen to be of wire stretched between side rods, the wire runs flat across the cathode. This valve was a purpose built series voltage regulator and so designed for a hard service life whilst supplying a regulated voltage to other stages in professional equipment.','7971 CV4060 CV8077 L.5B/280K',NULL,NULL,'inferred',NULL);
