INSERT INTO "valve_type" VALUES('GS14','GS-14','microwave oscillator triode',NULL,NULL,NULL,6.3,NULL,450.0,28.0,NULL,NULL,2.0,NULL,'generator triode for amplifying, generating and multiplying centimetre/decimetre-wave oscillations',NULL,'G\GS14.pdf',NULL,'confirmed','Application field: generator and high frequency amplifier; | Envelope: titanium-ceramic, silver coated leads; | Dimensions (D x H), mm: 25 x 37; | Mass, gr: 25; | Filament voltage, V: 6.3; | Filament current, A : 0.73 (+/-) 0.07; | Typical Anode current, mA: 30; | Typical Anode voltage, V: 350; | Mutual conductance, mA/V: 20; | Max anode power, W: 88; | Maximum operating frequency: about or over 4 GHz; | Ambient operating temperature: -60 ... +100 deg. Celsius; | Max envelope temperature: +200 deg. Celsius; | Base: special type, four leads, anode located on top, grid in the middle, cathode and filament at bottom; | Each tube contains approximately 0.25g Silver (Ag).');
