INSERT INTO "valve_type" VALUES('QP22B','QP22B','double pentode (QPP output)','british (GEC/Osram code)',NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,'The QP22B is a battery double pentode, designed for quiescent push pull class B audio amplification. Class B amplification produces considerable distortion at the points in the cycle where the valves move from cut-off to conduction. The advantage is that when not driven by a signal the power consumption from the HT battery is low. The total power output is 1 Watt and was aimed at driving a loudspeaker, quite a luxury when battery powered.','240QP K77B',NULL,NULL,'inferred',NULL);
